using System;
using System.Buffers.Binary;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;

namespace OpenScct.Master.Player;

/// <summary>Bounded PNG attachments generated by the game, published only with a reviewed report.</summary>
internal static class ReportScreenshot
{
    internal const int MaximumBytes = 2 * 1024 * 1024;
    internal const int MaximumText = (MaximumBytes + 2) / 3 * 4;
    internal const string Route = "/help/report-screenshots/";

    internal static byte[]? Decode(string text)
    {
        if (text.Length == 0 || text.Length > MaximumText) return null;
        byte[] png;
        try { png = Convert.FromBase64String(text); }
        catch (FormatException) { return null; }
        return Validate(png);
    }

    internal static byte[]? Validate(byte[] png)
    {
        if (png.Length > MaximumBytes || png.Length < 57 ||
            !png.AsSpan(0, 8).SequenceEqual(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 })) return null;
        int width = 0, height = 0, channels = 0;
        bool data = false, ended = false;
        using var compressed = new MemoryStream();
        for (int offset = 8; offset < png.Length;)
        {
            if (png.Length - offset < 12) return null;
            uint length = BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(offset, 4));
            if (length > png.Length - offset - 12) return null;
            int count = (int)length;
            ReadOnlySpan<byte> typeAndData = png.AsSpan(offset + 4, count + 4);
            uint crc = uint.MaxValue;
            foreach (byte b in typeAndData)
            {
                crc ^= b;
                for (int bit = 0; bit < 8; bit++) crc = (crc >> 1) ^ ((crc & 1) == 0 ? 0u : 0xedb88320u);
            }
            if (~crc != BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(offset + count + 8, 4))) return null;
            ReadOnlySpan<byte> chunk = png.AsSpan(offset + 8, count);
            string type = System.Text.Encoding.ASCII.GetString(png, offset + 4, 4);
            if (offset == 8 && type != "IHDR") return null;
            if (type == "IHDR")
            {
                if (offset != 8 || count != 13) return null;
                uint w = BinaryPrimitives.ReadUInt32BigEndian(chunk[..4]), h = BinaryPrimitives.ReadUInt32BigEndian(chunk.Slice(4, 4));
                if (w is 0 or > 4096 || h is 0 or > 4096 || chunk[8] != 8 || chunk[9] is not (2 or 6) ||
                    chunk[10] != 0 || chunk[11] != 0 || chunk[12] != 0) return null;
                width = (int)w; height = (int)h; channels = chunk[9] == 2 ? 3 : 4;
            }
            else if (type == "IDAT") { data = true; compressed.Write(chunk); }
            else if (type == "IEND")
            {
                if (!data || count != 0 || offset + 12 != png.Length) return null;
                ended = true;
            }
            else if (type is not ("sRGB" or "gAMA" or "cHRM" or "pHYs")) return null;
            offset += count + 12;
        }
        if (!ended) return null;
        compressed.Position = 0;
        try
        {
            using var pixels = new ZLibStream(compressed, CompressionMode.Decompress);
            byte[] row = new byte[width * channels];
            for (int y = 0; y < height; y++)
            {
                if (pixels.ReadByte() is < 0 or > 4) return null;
                pixels.ReadExactly(row);
            }
            if (pixels.ReadByte() != -1) return null;
        }
        catch (Exception error) when (error is IOException or InvalidDataException) { return null; }
        return png;
    }

    internal static string Id(byte[] png) => Convert.ToHexStringLower(SHA256.HashData(png));
    internal static bool ValidId(string id) => id.Length == 64 && System.Linq.Enumerable.All(id, c => c is >= '0' and <= '9' or >= 'a' and <= 'f');
    internal static string PathFor(MasterOptions options, string id) => Path.Combine(options.ResolvePath("report-screenshots"), id + ".png");
    internal static void Save(MasterOptions options, byte[] png)
    {
        string file = PathFor(options, Id(png));
        Directory.CreateDirectory(Path.GetDirectoryName(file)!);
        // Atomic rename prevents concurrent readers from seeing a partial image.
        string temporary = file + "." + Guid.NewGuid().ToString("N") + ".tmp";
        try { File.WriteAllBytes(temporary, png); File.Move(temporary, file, overwrite: true); }
        finally { if (File.Exists(temporary)) File.Delete(temporary); }
    }
}
